gagg(){return"\u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0645\u0629 \u0645\u0648\u062c\u0648\u062f\u0629 \u0644\u062f\u064a\u0643 \u0645\u0633\u0628\u0642\u0627\u064b"},
gTO(){return"\u062a\u0639\u0630\u0651\u0631\u062a \u0642\u0631\u0627\u0621\u0629 \u0647\u0630\u0627 \u0627\u0644\u0645\u0633\u062a\u0646\u062f"},
gafV(){return"\u0644\u0645 \u0646\u0642\u0631\u0623 \u0625\u062d\u062f\u0649 \u0627\u0644\u0642\u064a\u0645 \u0628\u062b\u0642\u0629 \u0643\u0627\u0641\u064a\u0629 \u0644\u0625\u0636\u0627\u0641\u062a\u0647\u0627 \u0643\u0645\u0627 \u0647\u064a. \u0627\u0643\u062a\u0628\u0647\u0627 \u0628\u0646\u0641\u0633\u0643 \u0643\u0645\u0627 \u062a\u0631\u0627\u0647\u0627 \u0641\u064a \u0627\u0644\u0648\u0631\u0642\u0629\u060c \u062b\u0645 \u0627\u0636\u063a\u0637 \u2713 \u0639\u0644\u0649 \u0633\u0637\u0631\u0647\u0627."},
gafW(){return"\u0639\u0644\u0649 \u0625\u062d\u062f\u0649 \u0627\u0644\u0642\u064a\u0645 \u0645\u0644\u0627\u062d\u0638\u0629 \u062a\u0645\u0646\u0639 \u0642\u0628\u0648\u0644\u0647\u0627 \u0643\u0645\u0627 \u0642\u0631\u0623\u0646\u0627\u0647\u0627. \u0627\u0643\u062a\u0628\u0647\u0627 \u0628\u0646\u0641\u0633\u0643 \u0645\u0646 \u0627\u0644\u0648\u0631\u0642\u0629\u060c \u0623\u0648 \u0623\u0632\u0644 \u0633\u0637\u0631\u0647\u0627."},
gafQ(){return"\u0627\u0644\u0642\u064a\u0645\u0629 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0649 \u0627\u0644\u0637\u0628\u064a\u0639\u064a \u0644\u0627 \u062a\u064f\u0636\u0627\u0641 \u0636\u0645\u0646 \u0642\u0628\u0648\u0644 \u062c\u0645\u0627\u0639\u064a \u2014 \u0623\u0643\u0651\u062f\u0647\u0627 \u0628\u0646\u0641\u0633\u0643 \u0639\u0644\u0649 \u0633\u0637\u0631\u0647\u0627."},
gafT(){return"\u0628\u0642\u064a \u0633\u0637\u0631 \u0644\u0645 \u062a\u0642\u0631\u0651\u0631 \u0628\u0634\u0623\u0646\u0647. \u0623\u0643\u0651\u062f \u0643\u0644 \u0633\u0637\u0631 \u0623\u0648 \u0623\u0632\u0644\u0647\u060c \u062b\u0645 \u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629."},
