gafZ(){return"\u0623\u062d\u062f \u0627\u0644\u0633\u0637\u0648\u0631 \u0628\u0644\u0627 \u0642\u064a\u0645\u0629. \u0627\u0643\u062a\u0628 \u0627\u0644\u0642\u064a\u0645\u0629 \u0643\u0645\u0627 \u062a\u0631\u0627\u0647\u0627 \u0641\u064a \u0627\u0644\u0648\u0631\u0642\u0629\u060c \u0623\u0648 \u0623\u0632\u0644 \u0627\u0644\u0633\u0637\u0631."},
gafY(){return"\u0623\u062d\u062f \u0627\u0644\u0633\u0637\u0648\u0631 \u0628\u0644\u0627 \u0641\u062d\u0635 \u0645\u062d\u062f\u064e\u0651\u062f. \u0627\u062e\u062a\u0631 \u0627\u0633\u0645 \u0627\u0644\u0641\u062d\u0635\u060c \u0623\u0648 \u0623\u0632\u0644 \u0627\u0644\u0633\u0637\u0631."},
gafS(){return"\u0625\u062d\u062f\u0649 \u0627\u0644\u0642\u064a\u0645 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0649 \u0627\u0644\u0645\u0645\u0643\u0646 \u0644\u0647\u0630\u0627 \u0627\u0644\u0641\u062d\u0635 \u2014 \u0627\u0644\u0623\u0631\u062c\u062d \u0623\u0646\u0647\u0627 \u0642\u0631\u0627\u0621\u0629 \u062e\u0627\u0637\u0626\u0629. \u0631\u0627\u062c\u0639\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u0648\u0631\u0642\u0629."},
