gafR(){return"\u062d\u064f\u0630\u0641 \u0627\u0644\u0645\u0633\u062a\u0646\u062f \u0627\u0644\u0630\u064a \u062c\u0627\u0621\u062a \u0645\u0646\u0647 \u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0645\u060c \u0641\u0644\u0627 \u064a\u0645\u0643\u0646 \u0625\u0636\u0627\u0641\u062a\u0647\u0627 \u0625\u0644\u0649 \u0633\u062c\u0644\u0651\u0643."},
gafX(){return"\u0623\u064f\u0636\u064a\u0641\u062a \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0645\u0633\u0628\u0642\u0627\u064b \u0623\u0648 \u0644\u0645 \u062a\u0639\u062f \u0645\u062a\u0627\u062d\u0629. \u0623\u0639\u062f \u0641\u062a\u062d \u0627\u0644\u0634\u0627\u0634\u0629."},
gagG(){return"\u0623\u064f\u0636\u064a\u0641\u062a \u0627\u0644\u0642\u064a\u0645 \u0625\u0644\u0649 \u0633\u062c\u0644\u0651\u0643"},
gagF(){return"\u0623\u064f\u062e\u0641\u064a\u062a \u0627\u0644\u0642\u064a\u0645\u0629 \u0645\u0646 \u0633\u062c\u0644\u0651\u0643 \u2014 \u0644\u0645 \u062a\u064f\u062d\u0630\u0641\u060c \u0648\u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u0639\u0627\u062f\u062a\u0647\u0627 \u0644\u0627\u062d\u0642\u0627\u064b"},
