gaoF(){return"\u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629"},
aem(a,b){return"\u0635\u0641\u062d\u0629 "+a+" \u0645\u0646 "+b},
